<script setup lang="ts">
import { ref } from 'vue'; import { useToast } from 'primevue/usetoast'; import Dialog from 'primevue/dialog'; import Button from 'primevue/button'; import Select from 'primevue/select'; import Textarea from 'primevue/textarea';
import AppShell from '../layouts/AppShell.vue'; import RequestTable from '../components/RequestTable.vue'; import RequestDetail from '../components/RequestDetail.vue';
import { departments, requests, trace } from '../services/mock'; import type { RepairRequest } from '../types';
const toast=useToast(), items=ref([...requests]), selected=ref<RepairRequest|null>(items.value.find(r=>r.status==='HUMAN_REVIEW')||items.value[0]), assignOpen=ref(false), closeOpen=ref(false), department=ref('ELE'), note=ref('');
function resolve(action:'ASSIGN'|'CLOSE'){ if(!selected.value||!note.value.trim())return;if(action==='ASSIGN'){selected.value.status='ASSIGNED';selected.value.assigned_department=department.value;selected.value.review_reason=null;}else selected.value.status='CLOSED';items.value=[...items.value];assignOpen.value=false;closeOpen.value=false;toast.add({severity:'success',summary:action==='ASSIGN'?'수동 배정 완료':'요청 종결',detail:`${selected.value.id} 처리가 완료되었습니다.`,life:2500});note.value=''; }
</script>
<template><AppShell><template #role>어드민 · MCC</template><div class="page-title"><div><span>CONTROL DESK</span><h1>정비상황실 운영 콘솔</h1><p>전체 요청과 자동 배정 중지 건을 한 화면에서 관리합니다.</p></div><div class="rag-health"><i class="pi pi-database"/><div><b>RAG READY</b><small>Release v1 · Index 4/4</small></div></div></div><div class="metric-strip"><div><small>전체 요청</small><b>{{ items.length }}</b></div><div><small>사람 검토</small><b class="danger-text">{{ items.filter(r=>r.status==='HUMAN_REVIEW').length }}</b></div><div><small>자동 배정률</small><b>84%</b></div><div><small>평균 처리</small><b>42s</b></div></div><div class="console-grid"><div class="queue-panel"><div class="panel-head"><div><b>전체 요청 큐</b><small>HUMAN_REVIEW 우선 표시</small></div><div class="filter-tabs"><Button label="전체" size="small"/><Button label="사람 검토" severity="danger" outlined size="small"/></div></div><RequestTable :items="items" :selected="selected" @select="selected=$event"/></div><RequestDetail :request="selected" :trace="trace" mode="admin" @assign="assignOpen=true" @close="closeOpen=true"/></div><Dialog v-model:visible="assignOpen" modal header="수동 부서 배정" :style="{width:'480px'}"><div class="request-form"><label>담당 부서</label><Select v-model="department" :options="departments" optionLabel="name" optionValue="code" fluid/><label>검토 메모</label><Textarea v-model="note" rows="4" fluid placeholder="수동 배정 근거를 입력하세요."/></div><template #footer><Button label="취소" text @click="assignOpen=false"/><Button label="배정 확정" :disabled="!note.trim()" @click="resolve('ASSIGN')"/></template></Dialog><Dialog v-model:visible="closeOpen" modal header="요청 종결" :style="{width:'480px'}"><p class="dialog-copy">종결된 요청은 자동 배정되지 않습니다. 종결 사유를 입력하세요.</p><Textarea v-model="note" rows="4" fluid/><template #footer><Button label="취소" text @click="closeOpen=false"/><Button label="요청 종결" severity="danger" :disabled="!note.trim()" @click="resolve('CLOSE')"/></template></Dialog></AppShell></template>
